content:
:root {
  --color-bg-base: #0f172a;
  --color-bg-card: rgba(30, 41, 59, 0.85);
  --color-bg-card-hover: rgba(51, 65, 85, 0.9);
  --color-primary: #38bdf8;
  --color-primary-glow: rgba(56, 189, 248, 0.35);
  --color-accent: #f59e0b;
  --color-accent-glow: rgba(245, 158, 11, 0.3);
  --color-success: #10b981;
  --color-danger: #ef4444;
  --color-text-main: #f8fafc;
  --color-text-muted: #94a3b8;
  --color-text-sub: #cbd5e1;
  --color-border: rgba(148, 163, 184, 0.15);
  --color-key-bg: #1e293b;
  --color-key-border: #334155;
  --font-family-main: "Inter", "Noto Sans JP", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-family-mono: "JetBrains Mono", "Fira Code", monospace;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family-main);
  background-color: var(--color-bg-base);
  background-image: 
    radial-gradient(at 0% 0%, rgba(56, 189, 248, 0.12) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(99, 102, 241, 0.12) 0px, transparent 50%),
    radial-gradient(at 50% 50%, rgba(15, 23, 42, 1) 0px, transparent 100%);
  background-attachment: fixed;
  color: var(--color-text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  overflow-x: hidden;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#root {
  width: 100%;
  max-width: 960px;
  min-height: 100vh;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
}

/* アプリ全体レイアウト */
.typing-app {
  width: 100%;
  padding: 1.5rem 1rem 3rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  position: relative;
  min-height: 100vh;
}

/* ヘッダー領域 */
.header {
  text-align: center;
  margin-bottom: 0.5rem;
}

.title {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 4px 16px rgba(56, 189, 248, 0.2);
}

.subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-top: 0.35rem;
  font-weight: 500;
}

/* リアルタイム統計バー */
.stats-bar {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
  width: 100%;
}

.stat-item {
  background: var(--color-bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--color-border);
  border-radius: 0.875rem;
  padding: 0.75rem 0.5rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2);
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.stat-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.25rem;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  font-family: var(--font-family-mono);
  color: var(--color-text-main);
}

.timer-highlight {
  color: var(--color-accent);
  text-shadow: 0 0 12px var(--color-accent-glow);
}

/* お題表示カード */
.game-card {
  position: relative;
  background: var(--color-bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--color-border);
  border-radius: 1.25rem;
  padding: 2.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  min-height: 220px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  overflow: hidden;
}

.prompt-kanji {
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: 0.05em;
  text-align: center;
}

.prompt-kana {
  font-size: 1.15rem;
  font-weight: 500;
  color: var(--color-text-muted);
  letter-spacing: 0.05em;
  text-align: center;
}

.prompt-romaji {
  font-family: var(--font-family-mono);
  font-size: 1.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.15rem;
  padding: 0.5rem 1rem;
  background: rgba(15, 23, 42, 0.5);
  border-radius: 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.romaji-char {
  display: inline-block;
  transition: all 0.15s ease;
  min-width: 1.1ch;
  text-align: center;
}

.char-typed {
  color: #64748b;
  text-decoration: none;
}

.char-current {
  color: #38bdf8;
  position: relative;
  font-weight: 800;
  transform: translateY(-2px);
  text-shadow: 0 0 12px var(--color-primary-glow);
}

.char-current::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 3px;
  background-color: var(--color-primary);
  border-radius: 2px;
  box-shadow: 0 0 8px var(--color-primary-glow);
  animation: cursor-pulse 1s infinite alternate;
}

@keyframes cursor-pulse {
  0% { opacity: 0.4; }
  100% { opacity: 1; }
}

.char-remaining {
  color: #f1f5f9;
}

/* スタート・一時停止等のオーバーレイ */
.start-overlay {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.92);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-radius: 1.25rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  z-index: 10;
  gap: 1.25rem;
  text-align: center;
}

.instructions {
  font-size: 1rem;
  color: var(--color-text-sub);
  max-width: 480px;
  line-height: 1.6;
}

/* ボタン */
.btn {
  font-family: inherit;
  font-weight: 700;
  font-size: 1rem;
  padding: 0.85rem 2rem;
  border-radius: 9999px;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  outline: none;
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background: linear-gradient(135deg, #0284c7 0%, #38bdf8 100%);
  color: #ffffff;
  box-shadow: 0 4px 14px 0 rgba(56, 189, 248, 0.35);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #0369a1 0%, #0ea5e9 100%);
  box-shadow: 0 6px 20px rgba(56, 189, 248, 0.5);
  transform: translateY(-1px);
}

.btn-secondary {
  background: rgba(51, 65, 85, 0.8);
  color: #f8fafc;
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.btn-secondary:hover {
  background: rgba(71, 85, 105, 0.9);
}

/* 仮想キーボードセクション */
.keyboard-section {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  padding: 1rem;
  background: var(--color-bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 1.25rem;
  border: 1px solid var(--color-border);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
  user-select: none;
}

.keyboard-row {
  display: flex;
  gap: 0.35rem;
  justify-content: center;
  width: 100%;
}

.key-cap {
  font-family: var(--font-family-mono);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-sub);
  background: var(--color-key-bg);
  border: 1px solid var(--color-key-border);
  box-shadow: 0 2px 0 #0f172a, 0 3px 5px rgba(0, 0, 0, 0.3);
  border-radius: 0.5rem;
  height: 2.75rem;
  min-width: 2.25rem;
  padding: 0 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.1s ease;
  outline: none;
}

.key-cap:hover {
  background: #334155;
  color: #ffffff;
}

.key-cap:active {
  transform: translateY(2px);
  box-shadow: 0 0 0 #0f172a;
}

.key-active {
  background: #0284c7;
  color: #ffffff;
  border-color: #38bdf8;
  transform: translateY(1px);
  box-shadow: 0 1px 0 #0f172a, 0 0 15px var(--color-primary-glow);
  font-weight: 800;
}

.key-space {
  min-width: 14rem;
}

/* モバイル入力補助エリア */
.mobile-input-area {
  display: flex;
  justify-content: center;
  margin-top: 0.25rem;
}

.hidden-input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  width: 1px;
  height: 1px;
}

.mobile-tap-button {
  background: rgba(56, 189, 248, 0.1);
  border: 1px dashed var(--color-primary);
  color: var(--color-primary);
  padding: 0.6rem 1.25rem;
  border-radius: 0.75rem;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s ease;
}

.mobile-tap-button:hover,
.mobile-tap-button:active {
  background: rgba(56, 189, 248, 0.2);
}

/* 結果画面・モーダル */
.result-card {
  background: var(--color-bg-card);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 1.5rem;
  padding: 2.25rem 2rem;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.75rem;
  max-width: 520px;
  width: 100%;
  margin: 0 auto;
  animation: modal-fade-in 0.3s ease-out;
}

@keyframes modal-fade-in {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(10px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.result-title {
  font-size: 2rem;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.01em;
  text-align: center;
}

.result-rank-badge {
  font-size: 1.25rem;
  font-weight: 800;
  padding: 0.5rem 1.5rem;
  border-radius: 9999px;
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #ffffff;
  box-shadow: 0 4px 15px var(--color-accent-glow);
  letter-spacing: 0.05em;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.result-message {
  font-size: 1rem;
  color: var(--color-text-sub);
  text-align: center;
  margin-top: -0.5rem;
  line-height: 1.5;
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  width: 100%;
}

.result-stat {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(148, 163, 184, 0.12);
  border-radius: 1rem;
  padding: 1.15rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.result-stat .stat-label {
  font-size: 0.8rem;
  margin-bottom: 0.35rem;
}

.result-stat .stat-value {
  font-size: 1.75rem;
  color: #ffffff;
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  .typing-app {
    padding: 1rem 0.5rem 2rem 0.5rem;
    gap: 1rem;
  }

  .title {
    font-size: 1.75rem;
  }

  .subtitle {
    font-size: 0.85rem;
  }

  .stats-bar {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.5rem;
  }

  .stat-item {
    padding: 0.5rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }

  .game-card {
    padding: 1.5rem 0.75rem;
    min-height: 180px;
    gap: 0.75rem;
  }

  .prompt-kanji {
    font-size: 1.65rem;
  }

  .prompt-kana {
    font-size: 1rem;
  }

  .prompt-romaji {
    font-size: 1.25rem;
    padding: 0.35rem 0.5rem;
    letter-spacing: 0.05em;
  }

  .keyboard-section {
    padding: 0.5rem 0.25rem;
    gap: 0.25rem;
  }

  .keyboard-row {
    gap: 0.2rem;
  }

  .key-cap {
    height: 2.25rem;
    min-width: 1.75rem;
    font-size: 0.75rem;
    padding: 0 0.25rem;
    border-radius: 0.35rem;
  }

  .key-space {
    min-width: 8rem;
  }

  .result-card {
    padding: 1.5rem 1rem;
    gap: 1.25rem;
  }

  .result-title {
    font-size: 1.6rem;
  }

  .result-grid {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .result-stat {
    padding: 0.85rem;
  }
}

@media (max-width: 380px) {
  .key-cap {
    min-width: 1.5rem;
    height: 2rem;
    font-size: 0.7rem;
  }

  .prompt-kanji {
    font-size: 1.4rem;
  }

  .prompt-romaji {
    font-size: 1.1rem;
  }
}

export interface WordItem {
  id: number;
  kanji: string;
  kana: string;
  romaji: string;
}

export interface GameState {
  status: 'ready' | 'playing' | 'finished';
  timeLeft: number;
  correctChars: number;
  totalCharsTyped: number;
  missCount: number;
  currentWordIndex: number;
  typedInCurrentWord: string;
}

export interface TypingStats {
  correctChars: number;
  missCount: number;
  accuracy: number;
  kpm: number;
  rank: string;
}

export interface VirtualKeyboardProps {
  activeKey: string;
  onKeyPress: (key: string) => void;
}

export interface ResultModalProps {
  stats: TypingStats;
  onRetry: () => void;
}

