import { FC } from 'react';
import { VirtualKeyboardProps } from '../types';

const KEYBOARD_ROWS = [
  ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '-'],
  ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
  ['z', 'x', 'c', 'v', 'b', 'n', 'm']
];

const VirtualKeyboard: FC<VirtualKeyboardProps> = ({ activeKey = '', onKeyPress }) => {
  const normalizedActiveKey = activeKey.toLowerCase();

  const handleKeyClick = (key: string) => {
    onKeyPress?.(key);
  };

  return (
    <div className="keyboard-section" aria-label="仮想キーボード">
      {KEYBOARD_ROWS.map((row, rowIndex) => (
        <div key={`row-${rowIndex}`} className="keyboard-row">
          {row.map((char) => {
            const isActive = normalizedActiveKey === char;
            const keyClass = isActive ? 'key-cap key-active' : 'key-cap';

            return (
              <button
                key={char}
                type="button"
                className={keyClass}
                onClick={() => handleKeyClick(char)}
                tabIndex={-1}
                aria-pressed={isActive}
              >
                {char.toUpperCase()}
              </button>
            );
          })}
        </div>
      ))}
    </div>
  );
};

export default VirtualKeyboard;

import { FC } from 'react';
import { ResultModalProps } from '../types';

const ScoreBoard: FC<ResultModalProps> = ({
  stats = { correctChars: 0, missCount: 0, accuracy: 0, kpm: 0, rank: 'ビギナー' },
  onRetry
}) => {
  const getRankDescription = (rank: string) => {
    switch (rank) {
      case 'S+ 神速級':
        return '圧倒的な打鍵スピード！まさに神がかり的なタイピング技術です！';
      case 'S級 マスター':
        return 'プロレベルのタイピング力！指先が流れるように動いています！';
      case 'A級 エキスパート':
        return '非常に正確で素早い入力です！ビジネスでも即戦力のスピード！';
      case 'B級 スタンダード':
        return '普段のタイピング作業をスムーズにこなせる充分な実力です！';
      case 'C級 ビギナー':
        return '基本はバッチリ！ホームポジションを意識してさらにスコアを伸ばそう！';
      default:
        return 'まずは落ち着いて正確な入力を心がけてみましょう！';
    }
  };

  return (
    <div className="result-card">
      <h2 className="result-title">タイムアップ！</h2>

      <div className="result-rank-badge">
        称号: {stats.rank}
      </div>

      <p className="result-message">
        {getRankDescription(stats.rank)}
      </p>

      <div className="result-grid">
        <div className="result-stat">
          <span className="stat-label">正確に入力した文字数</span>
          <span className="stat-value">{stats.correctChars} <small style={{ fontSize: '1rem', fontWeight: 500 }}>文字</small></span>
        </div>

        <div className="result-stat">
          <span className="stat-label">タイピング速度 (KPM)</span>
          <span className="stat-value">{stats.kpm} <small style={{ fontSize: '1rem', fontWeight: 500 }}>打/分</small></span>
        </div>

        <div className="result-stat">
          <span className="stat-label">入力正解率</span>
          <span className="stat-value">{stats.accuracy}%</span>
        </div>

        <div className="result-stat">
          <span className="stat-label">ミス打鍵数</span>
          <span className="stat-value">{stats.missCount} <small style={{ fontSize: '1rem', fontWeight: 500 }}>回</small></span>
        </div>
      </div>

      <button
        type="button"
        className="btn btn-primary"
        onClick={() => onRetry?.()}
      >
        もう一度遊ぶ
      </button>
    </div>
  );
};

export default ScoreBoard;

import { useState, useEffect, useRef, useCallback, FC, ChangeEvent } from 'react';
import { GameState, TypingStats } from './types';
import { WORDS } from './data/words';
import VirtualKeyboard from './components/VirtualKeyboard';
import ScoreBoard from './components/ScoreBoard';

const GAME_DURATION = 60;

const App: FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    status: 'ready',
    timeLeft: GAME_DURATION,
    correctChars: 0,
    totalCharsTyped: 0,
    missCount: 0,
    currentWordIndex: 0,
    typedInCurrentWord: ''
  });

  const hiddenInputRef = useRef<HTMLInputElement>(null);

  // 現在のお題
  const currentWord = WORDS[gameState.currentWordIndex % WORDS.length];
  // 現在打ち込むべき文字
  const activeChar = currentWord ? currentWord.romaji[gameState.typedInCurrentWord.length] || '' : '';

  // ランク計算
  const calculateRank = (chars: number, accuracy: number): string => {
    if (chars >= 350 && accuracy >= 95) return 'S+ 神速級';
    if (chars >= 280 && accuracy >= 90) return 'S級 マスター';
    if (chars >= 200 && accuracy >= 85) return 'A級 エキスパート';
    if (chars >= 130 && accuracy >= 75) return 'B級 スタンダード';
    return 'C級 ビギナー';
  };

  // 入力処理ロジック
  const handleKeyInput = useCallback((key: string) => {
    setGameState((prev) => {
      if (prev.status !== 'playing') return prev;

      const word = WORDS[prev.currentWordIndex % WORDS.length];
      const targetChar = word.romaji[prev.typedInCurrentWord.length];

      if (!targetChar) return prev;

      const isCorrect = key.toLowerCase() === targetChar.toLowerCase();

      if (isCorrect) {
        const nextTyped = prev.typedInCurrentWord + targetChar;
        const isWordFinished = nextTyped.length >= word.romaji.length;

        return {
          ...prev,
          correctChars: prev.correctChars + 1,
          totalCharsTyped: prev.totalCharsTyped + 1,
          typedInCurrentWord: isWordFinished ? '' : nextTyped,
          currentWordIndex: isWordFinished ? prev.currentWordIndex + 1 : prev.currentWordIndex
        };
      } else {
        return {
          ...prev,
          missCount: prev.missCount + 1,
          totalCharsTyped: prev.totalCharsTyped + 1
        };
      }
    });
  }, []);

  // ゲームスタート
  const startGame = () => {
    setGameState({
      status: 'playing',
      timeLeft: GAME_DURATION,
      correctChars: 0,
      totalCharsTyped: 0,
      missCount: 0,
      currentWordIndex: 0,
      typedInCurrentWord: ''
    });

    if (hiddenInputRef.current) {
      hiddenInputRef.current.focus();
    }
  };

  // もう一度遊ぶ
  const handleRetry = () => {
    startGame();
  };

  // カウントダウンタイマー
  useEffect(() => {
    if (gameState.status !== 'playing') return;

    const timerId = window.setInterval(() => {
      setGameState((prev) => {
        if (prev.timeLeft <= 1) {
          clearInterval(timerId);
          return {
            ...prev,
            timeLeft: 0,
            status: 'finished'
          };
        }
        return {
          ...prev,
          timeLeft: prev.timeLeft - 1
        };
      });
    }, 1000);

    return () => clearInterval(timerId);
  }, [gameState.status]);

  // キーボードイベントリスナー（PC用）
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (gameState.status === 'ready') {
        if (e.key === ' ' || e.key === 'Enter') {
          e.preventDefault();
          startGame();
        }
        return;
      }

      if (gameState.status === 'finished') {
        if (e.key === ' ' || e.key === 'Enter') {
          e.preventDefault();
          handleRetry();
        }
        return;
      }

      if (gameState.status !== 'playing') return;

      // 英数字およびハイフン、スペースのみ処理
      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        handleKeyInput(e.key);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState.status, handleKeyInput]);

  // スマホ用隠し入力の変更検知
  const handleHiddenInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val.length > 0 && gameState.status === 'playing') {
      const lastChar = val.slice(-1);
      handleKeyInput(lastChar);
    }
    e.target.value = '';
  };

  const focusHiddenInput = () => {
    if (hiddenInputRef.current) {
      hiddenInputRef.current.focus();
    }
  };

  // 統計値の計算
  const accuracy = gameState.totalCharsTyped > 0
    ? Math.round((gameState.correctChars / gameState.totalCharsTyped) * 100)
    : 100;

  const elapsedTime = GAME_DURATION - gameState.timeLeft;
  const kpm = elapsedTime > 0
    ? Math.round((gameState.correctChars / elapsedTime) * 60)
    : 0;

  const stats: TypingStats = {
    correctChars: gameState.correctChars,
    missCount: gameState.missCount,
    accuracy,
    kpm,
    rank: calculateRank(gameState.correctChars, accuracy)
  };

  return (
    <div className="typing-app">
      <header className="header">
        <h1 className="title">60秒ローマ字タイピング</h1>
        <p className="subtitle">制限時間60秒間で正確に打てた文字数を競うタイピング練習ゲーム</p>
      </header>

      {/* 統計バー */}
      <div className="stats-bar">
        <div className="stat-item">
          <span className="stat-label">残り時間</span>
          <span className="stat-value timer-highlight">{gameState.timeLeft}秒</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">正しく打った文字数</span>
          <span className="stat-value">{gameState.correctChars}文字</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">タイピング速度</span>
          <span className="stat-value">{kpm} KPM</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">正確率</span>
          <span className="stat-value">{accuracy}%</span>
        </div>
      </div>

      {/* メインゲーム領域 / 結果モーダル */}
      {gameState.status === 'finished' ? (
        <ScoreBoard stats={stats} onRetry={handleRetry} />
      ) : (
        <div className="game-card">
          {gameState.status === 'ready' && (
            <div className="start-overlay">
              <p className="instructions">
                「スタート」ボタンまたはスペースキーを押すと60秒のタイピング測定が始まります。
                表示されるローマ字をキーボードで入力してください。
              </p>
              <button
                type="button"
                className="btn btn-primary"
                onClick={startGame}
              >
                タイピングを開始する
              </button>
            </div>
          )}

          <div className="prompt-kanji">{currentWord.kanji}</div>
          <div className="prompt-kana">{currentWord.kana}</div>

          <div className="prompt-romaji">
            {currentWord.romaji.split('').map((char, index) => {
              let charClass = 'romaji-char char-remaining';
              if (index < gameState.typedInCurrentWord.length) {
                charClass = 'romaji-char char-typed';
              } else if (index === gameState.typedInCurrentWord.length) {
                charClass = 'romaji-char char-current';
              }

              return (
                <span key={`${char}-${index}`} className={charClass}>
                  {char}
                </span>
              );
            })}
          </div>
        </div>
      )}

      {/* モバイル入力補助 */}
      <div className="mobile-input-area">
        <input
          ref={hiddenInputRef}
          type="text"
          className="hidden-input"
          onChange={handleHiddenInputChange}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck="false"
        />
        <button
          type="button"
          className="mobile-tap-button"
          onClick={focusHiddenInput}
        >
          📱 スマートフォン用キーボードを表示
        </button>
      </div>

      {/* 仮想キーボード */}
      <VirtualKeyboard
        activeKey={gameState.status === 'playing' ? activeChar : ''}
        onKeyPress={handleKeyInput}
      />
    </div>
  );
};

export default App;
